screenPanels.initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector('#price-tbody');
  let allRecords = [];

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusBadge = getStatusBadge(r.適用状態 || '有効');
      const price = r.適用単価 ? `¥${r.適用単価.toLocaleString()}` : '-';
      const startDate = r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString() : '-';
      const endDate = r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString() : '無期限';
      const updateDate = r.更新日時 ? new Date(r.更新日時).toLocaleDateString() : '-';

      return `
        <tr data-id="${r.適用期間ID || r.id}" class="cursor-pointer hover:bg-opacity-50" style="background: var(--bg-main);">
          <td>${r.顧客コード || '-'}</td>
          <td>${r.顧客名 || '-'}</td>
          <td>${r.商品コード || '-'}</td>
          <td>${r.商品名 || '-'}</td>
          <td class="font-medium">${price}</td>
          <td>${startDate}</td>
          <td>${endDate}</td>
          <td>${statusBadge}</td>
          <td>${updateDate}</td>
          <td>
            <button class="action-btn secondary text-xs px-2 py-1 detail-btn" data-id="${r.適用期間ID || r.id}">詳細</button>
            <button onclick="window.showScreen('scr-1780291508457')" class="action-btn secondary text-xs px-2 py-1 ml-1">履歴</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function getStatusBadge(status) {
    const badges = {
      '有効': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(34,197,94,0.1); color: #16a34a;">有効</span>',
      '無効': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(107,114,128,0.1); color: #6b7280;">無効</span>',
      '承認待ち': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(255,106,0,0.1); color: #ff6a00;">承認待ち</span>',
      '期限切れ': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(239,68,68,0.1); color: #dc2626;">期限切れ</span>'
    };
    return badges[status] || badges['有効'];
  }

  // 2. 初期データ描画とKPI更新
  function updateKPIs(records) {
    const activeCount = records.filter(r => r.適用状態 === '有効').length;
    const pendingCount = records.filter(r => r.適用状態 === '承認待ち').length;

    const thisMonth = new Date().toISOString().slice(0, 7);
    const monthlyUpdates = records.filter(r => 
      r.更新日時 && r.更新日時.slice(0, 7) === thisMonth
    ).length;

    const validPrices = records.filter(r => r.適用単価 && r.適用単価 > 0);
    const avgPrice = validPrices.length > 0 
      ? Math.round(validPrices.reduce((sum, r) => sum + r.適用単価, 0) / validPrices.length)
      : 0;

    container.querySelector('#kpi-active-count').textContent = activeCount;
    container.querySelector('#kpi-pending-count').textContent = pendingCount;
    container.querySelector('#kpi-monthly-updates').textContent = monthlyUpdates;
    container.querySelector('#kpi-avg-price').textContent = `¥${avgPrice.toLocaleString()}`;
  }

  function initCharts(records) {
    // 月別更新件数チャート
    const monthlyData = {};
    records.forEach(r => {
      if (r.更新日時) {
        const month = r.更新日時.slice(0, 7);
        monthlyData[month] = (monthlyData[month] || 0) + 1;
      }
    });

    const months = Object.keys(monthlyData).sort().slice(-6);
    const counts = months.map(m => monthlyData[m] || 0);

    new window.Chart(container.querySelector('#monthly-chart'), {
      type: 'line',
      data: {
        labels: months,
        datasets: [{
          label: '更新件数',
          data: counts,
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34,197,94,0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    // 承認状況分布チャート
    const statusData = {};
    records.forEach(r => {
      const status = r.適用状態 || '有効';
      statusData[status] = (statusData[status] || 0) + 1;
    });

    new window.Chart(container.querySelector('#status-chart'), {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusData),
        datasets: [{
          data: Object.values(statusData),
          backgroundColor: ['#22c55e', '#6b7280', '#ff6a00', '#dc2626']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // 初期データロード
  window.aivicApi.list(5).then(records => {
    if (records) {
      allRecords = records;
      renderRows(records);
      updateKPIs(records);
      initCharts(records);
    }
  });

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const customerSearch = container.querySelector('#customer-search').value.toLowerCase();
    const productCode = container.querySelector('#product-code-search').value.toLowerCase();
    const productName = container.querySelector('#product-name-search').value.toLowerCase();
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const statusFilter = container.querySelector('#status-filter').value;

    const records = await window.aivicApi.list(5);
    if (!records) return;

    const filtered = records.filter(r => {
      if (customerSearch && !(r.顧客名 || '').toLowerCase().includes(customerSearch) && 
          !(r.顧客コード || '').toLowerCase().includes(customerSearch)) return false;
      if (productCode && !(r.商品コード || '').toLowerCase().includes(productCode)) return false;
      if (productName && !(r.商品名 || '').toLowerCase().includes(productName)) return false;
      if (startDate && r.適用開始日 && r.適用開始日 < startDate) return false;
      if (endDate && r.適用開始日 && r.適用開始日> endDate) return false;
      if (statusFilter && r.適用状態 !== statusFilter) return false;
      return true;
    });

    allRecords = filtered;
    renderRows(filtered);
    updateKPIs(filtered);
  });

  // 4. 条件クリア
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#customer-search').value = '';
    container.querySelector('#product-code-search').value = '';
    container.querySelector('#product-name-search').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#status-filter').value = '';

    window.aivicApi.list(5).then(records => {
      if (records) {
        allRecords = records;
        renderRows(records);
        updateKPIs(records);
      }
    });
  });

  // 5. CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const records = await window.aivicApi.list(5);
    if (!records) return;

    const headers = ['顧客コード', '顧客名', '商品コード', '商品名', '適用単価', '適用開始日', '適用終了日', '適用状態', '更新日時'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...records.map(r => [
        r.顧客コード || '',
        r.顧客名 || '',
        r.商品コード || '',
        r.商品名 || '',
        r.適用単価 || '',
        r.適用開始日 || '',
        r.適用終了日 || '',
        r.適用状態 || '',
        r.更新日時 || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `顧客別単価一覧_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 6. 詳細表示
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const record = allRecords.find(r => (r.適用期間ID || r.id) === id);
      if (record) {
        showDetailPanel(record);
      }
    }
  });

  function showDetailPanel(record) {
    const panel = container.querySelector('#detail-panel');
    const currentInfo = container.querySelector('#current-price-info');
    const history = container.querySelector('#price-history');

    currentInfo.innerHTML = `
      <div><span style="color: var(--text-muted);">顧客:</span> ${record.顧客名 || '-'} (${record.顧客コード || '-'})</div>
      <div><span style="color: var(--text-muted);">商品:</span> ${record.商品名 || '-'} (${record.商品コード || '-'})</div>
      <div><span style="color: var(--text-muted);">現在単価:</span> <span class="font-bold" style="color: var(--primary);">¥${(record.適用単価 || 0).toLocaleString()}</span></div>
      <div><span style="color: var(--text-muted);">適用期間:</span> ${record.適用開始日 ? new Date(record.適用開始日).toLocaleDateString() : '-'} ～ ${record.適用終了日 ? new Date(record.適用終了日).toLocaleDateString() : '無期限'}</div>
      <div><span style="color: var(--text-muted);">状態:</span> ${getStatusBadge(record.適用状態 || '有効')}</div>
    `;

    // 履歴データの模擬表示
    history.innerHTML = `
      <div class="p-2 rounded" style="background: var(--bg-main);">
        <div class="text-xs" style="color: var(--text-muted);">${new Date().toLocaleDateString()}</div>
        <div>¥${(record.適用単価 || 0).toLocaleString()} (現在)</div>
      </div>
      <div class="p-2 rounded" style="background: var(--bg-main);">
        <div class="text-xs" style="color: var(--text-muted);">2024-01-15</div>
        <div>¥${Math.round((record.適用単価 || 1000) * 0.9).toLocaleString()} (前回)</div>
      </div>
    `;

    panel.style.display = 'block';
  }

  container.querySelector('#close-detail').addEventListener('click', () => {
    container.querySelector('#detail-panel').style.display = 'none';
  });
}

function(container, apiUrl, tables) {
  // DOM要素の取得
  const customerSelect = container.querySelector('#select-customer');
  const productSearchInput = container.querySelector('#input-product-search');
  const currentPriceInput = container.querySelector('#input-current-price');
  const newPriceInput = container.querySelector('#input-new-price');
  const requestTypeSelect = container.querySelector('#select-request-type');
  const startDateInput = container.querySelector('#input-start-date');
  const endDateInput = container.querySelector('#input-end-date');
  const reasonTextarea = container.querySelector('#textarea-reason');
  const approverSelect = container.querySelector('#select-approver');
  const previewContent = container.querySelector('#preview-content');
  const fileDropZone = container.querySelector('#file-drop-zone');
  const fileInput = container.querySelector('#file-input');
  const fileList = container.querySelector('#file-list');

  let selectedFiles = [];
  let selectedProduct = null;

  // プレビュー更新関数
  function updatePreview() {
    const customer = customerSelect.options[customerSelect.selectedIndex]?.text || '';
    const product = selectedProduct ? selectedProduct.name : '';
    const currentPrice = currentPriceInput.value;
    const newPrice = newPriceInput.value;
    const requestType = requestTypeSelect.options[requestTypeSelect.selectedIndex]?.text || '';
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const reason = reasonTextarea.value;
    const approver = approverSelect.options[approverSelect.selectedIndex]?.text || '';
    const priority = container.querySelector('input[name="priority"]:checked')?.value || '';

    const priorityText = { low: '低', medium: '中', high: '高' }[priority] || '';

    previewContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px 16px; font-size: 14px;">
        <div style="color: var(--text-muted);">顧客:</div>
        <div style="color: var(--text);">${customer}</div>
        <div style="color: var(--text-muted);">商品:</div>
        <div style="color: var(--text);">${product}</div>
        <div style="color: var(--text-muted);">申請種別:</div>
        <div style="color: var(--text);">${requestType}</div>
        <div style="color: var(--text-muted);">現在単価:</div>
        <div style="color: var(--text);">${currentPrice ? `¥${Number(currentPrice).toLocaleString()}` : ''}</div>
        <div style="color: var(--text-muted);">新単価:</div>
        <div style="color: var(--text);">${newPrice ? `¥${Number(newPrice).toLocaleString()}` : ''}</div>
        <div style="color: var(--text-muted);">適用期間:</div>
        <div style="color: var(--text);">${startDate}${endDate ? ` ～ ${endDate}` : ' ～ 無期限'}</div>
        <div style="color: var(--text-muted);">変更理由:</div>
        <div style="color: var(--text);">${reason}</div>
        <div style="color: var(--text-muted);">承認者:</div>
        <div style="color: var(--text);">${approver}</div>
        <div style="color: var(--text-muted);">緊急度:</div>
        <div style="color: var(--text);">${priorityText}</div>
        <div style="color: var(--text-muted);">添付ファイル:</div>
        <div style="color: var(--text);">${selectedFiles.length}件</div>
      </div>
    `;
  }

  // 商品検索
  container.querySelector('#btn-product-search').addEventListener('click', async () => {
    const keyword = productSearchInput.value.trim();
    if (!keyword) return;

    // 模擬的な商品検索結果
    const mockProducts = [
      { id: 'prod-001', name: 'スチールパイプ φ25mm', code: 'SP-025', currentPrice: 1200 },
      { id: 'prod-002', name: 'アルミパイプ φ30mm', code: 'AP-030', currentPrice: 1800 },
      { id: 'prod-003', name: '銅管 φ15mm', code: 'CP-015', currentPrice: 2500 },
      { id: 'prod-004', name: 'ステンレスパイプ φ20mm', code: 'SSP-020', currentPrice: 3200 }
    ];

    const results = mockProducts.filter(p => 
      p.name.includes(keyword) || p.code.includes(keyword)
    );

    if (results.length > 0) {
      selectedProduct = results[0];
      productSearchInput.value = `${selectedProduct.name} (${selectedProduct.code})`;
      currentPriceInput.value = selectedProduct.currentPrice;
      updatePreview();
    } else {
      alert('該当する商品が見つかりませんでした');
    }
  });

  // ファイルドロップ処理
  fileDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    fileDropZone.style.borderColor = 'var(--primary)';
    fileDropZone.style.backgroundColor = 'rgba(0,0,0,0.25)';
  });

  fileDropZone.addEventListener('dragleave', (e) => {
    e.preventDefault();
    fileDropZone.style.borderColor = 'rgba(255,255,255,0.3)';
    fileDropZone.style.backgroundColor = 'rgba(0,0,0,0.15)';
  });

  fileDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    fileDropZone.style.borderColor = 'rgba(255,255,255,0.3)';
    fileDropZone.style.backgroundColor = 'rgba(0,0,0,0.15)';

    const files = Array.from(e.dataTransfer.files);
    addFiles(files);
  });

  container.querySelector('#btn-file-select').addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    addFiles(files);
  });

  function addFiles(files) {
    selectedFiles = [...selectedFiles, ...files];
    renderFileList();
    updatePreview();
  }

  function renderFileList() {
    fileList.innerHTML = selectedFiles.map((file, index) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; background: rgba(0,0,0,0.25); border-radius: 4px; margin-bottom: 8px;">
        <span style="color: var(--text); font-size: 14px;">${file.name} (${(file.size / 1024).toFixed(1)}KB)</span>
        <button class="action-btn secondary" onclick="removeFile(${index})" style="padding: 4px 8px; font-size: 12px;">削除</button>
      </div>
    `).join('');
  }

  window.removeFile = function(index) {
    selectedFiles.splice(index, 1);
    renderFileList();
    updatePreview();
  };

  // フォーム変更時のプレビュー更新
  [customerSelect, newPriceInput, requestTypeSelect, startDateInput, endDateInput, reasonTextarea, approverSelect].forEach(element => {
    element.addEventListener('change', updatePreview);
    element.addEventListener('input', updatePreview);
  });

  container.querySelectorAll('input[name="priority"]').forEach(radio => {
    radio.addEventListener('change', updatePreview);
  });

  // 一時保存
  container.querySelector('#btn-draft-save').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.申請状態 = '下書き';

    const saved = await window.aivicApi.save(1, formData); // 単価更新申請テーブル
    if (saved) {
      alert('一時保存しました');
    }
  });

  // 申請実行
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = collectFormData();
    formData.申請状態 = '申請中';

    const saved = await window.aivicApi.save(1, formData); // 単価更新申請テーブル
    if (saved) {
      // 承認ワークフロー作成
      const workflowData = {
        申請ID: saved.申請ID,
        承認段階: 1,
        承認者ID: approverSelect.value,
        承認者名: approverSelect.options[approverSelect.selectedIndex]?.text || '',
        承認ステータス: '承認待ち',
        期限日時: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
        通知済フラグ: false
      };

      await window.aivicApi.save(2, workflowData); // 単価承認ワークフローテーブル

      alert('申請を送信しました');
      // フォームリセット
      container.querySelectorAll('input, select, textarea').forEach(el => {
        if (el.type !== 'radio') el.value = '';
      });
      selectedFiles = [];
      selectedProduct = null;
      renderFileList();
      updatePreview();
    }
  });

  function collectFormData() {
    const priority = container.querySelector('input[name="priority"]:checked')?.value || 'medium';

    return {
      顧客ID: customerSelect.value,
      商品ID: selectedProduct?.id || '',
      申請種別: requestTypeSelect.value,
      現在単価: currentPriceInput.value ? parseInt(currentPriceInput.value) : null,
      申請単価: parseInt(newPriceInput.value),
      適用開始日: startDateInput.value,
      適用終了日: endDateInput.value || null,
      申請理由: reasonTextarea.value,
      申請者ID: 'current-user-id', // 実際はログインユーザーID
      承認者ID: approverSelect.value,
      緊急度: priority
    };
  }

  function validateForm() {
    if (!customerSelect.value) {
      alert('顧客を選択してください');
      return false;
    }
    if (!selectedProduct) {
      alert('商品を選択してください');
      return false;
    }
    if (!newPriceInput.value) {
      alert('新単価を入力してください');
      return false;
    }
    if (!startDateInput.value) {
      alert('適用開始日を選択してください');
      return false;
    }
    if (!reasonTextarea.value.trim()) {
      alert('変更理由を入力してください');
      return false;
    }
    if (!approverSelect.value) {
      alert('承認者を選択してください');
      return false;
    }
    return true;
  }

  // 初期設定
  const today = new Date().toISOString().split('T')[0];
  startDateInput.value = today;
  updatePreview();
}

function(container, apiUrl, tables) {
  let selectedApplicationId = null;
  let currentApplications = [];

  // 緊急度バッジの生成
  function getPriorityBadge(priority) {
    const colors = {
      '高': { bg: 'rgba(239,68,68,0.15)', color: '#ef4444' },
      '中': { bg: 'rgba(245,158,11,0.15)', color: '#f59e0b' },
      '低': { bg: 'rgba(107,114,128,0.15)', color: '#6b7280' }
    };
    const style = colors[priority] || colors['低'];
    return `<span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${style.bg}; color: ${style.color};">${priority}</span>`;
  }

  // 変更率の計算と表示
  function getChangeRate(current, newPrice) {
    if (!current || current === 0) return '-';
    const rate = ((newPrice - current) / current * 100);
    const color = rate > 0 ? '#ef4444' : rate < 0 ? '#22c55e' : '#6b7280';
    const sign = rate > 0 ? '+' : '';
    return `<span style="color: ${color}; font-weight: 500;">${sign}${rate.toFixed(1)}%</span>`;
  }

  // 承認フロー進捗の表示
  function renderApprovalFlow(workflows) {
    const flowContainer = container.querySelector('#approval-flow');
    if (!workflows || workflows.length === 0) {
      flowContainer.innerHTML = '<div style="color: var(--text-muted); font-size: 13px;">承認フローが設定されていません</div>';
      return;
    }

    flowContainer.innerHTML = workflows.map(wf => {
      const statusColors = {
        '承認済み': { bg: 'rgba(34,197,94,0.15)', color: '#22c55e' },
        '承認待ち': { bg: 'rgba(245,158,11,0.15)', color: '#f59e0b' },
        '否認': { bg: 'rgba(239,68,68,0.15)', color: '#ef4444' },
        '保留': { bg: 'rgba(107,114,128,0.15)', color: '#6b7280' }
      };
      const style = statusColors[wf.承認ステータス] || statusColors['承認待ち'];

      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px;">
          <div>
            <div style="font-size: 13px; color: var(--text); font-weight: 500;">${wf.承認段階}次承認: ${wf.承認者名}</div>
            ${wf.承認日時 ? `<div style="font-size: 11px; color: var(--text-muted);">${new Date(wf.承認日時).toLocaleString()}</div>` : ''}
          </div>
          <span style="padding: 2px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${style.bg}; color: ${style.color};">${wf.承認ステータス}</span>
        </div>
      `;
    }).join('');
  }

  // 申請一覧の再描画
  function renderApplications(applications) {
    const tbody = container.querySelector('#workflow-tbody');
    if (!applications || applications.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 20px;">承認待ちの申請はありません</td></tr>';
      return;
    }

    tbody.innerHTML = applications.map(app => {
      const changeRate = getChangeRate(app.現在単価, app.申請単価);
      const deadline = new Date(app.期限日時 || Date.now() + 7*24*60*60*1000);
      const isOverdue = deadline < new Date();
      const deadlineColor = isOverdue ? '#ef4444' : '#f59e0b';

      return `
        <tr data-id="${app.申請ID}" style="cursor: pointer;" class="application-row">
          <td>${getPriorityBadge(app.優先度 || '中')}</td>
          <td style="font-size: 12px;">${new Date(app.作成日時).toLocaleDateString()}</td>
          <td style="font-weight: 500;">${app.顧客名 || '顧客' + app.顧客ID?.slice(-4)}</td>
          <td>${app.商品名 || '商品' + app.商品ID?.slice(-4)}</td>
          <td style="text-align: right;">¥${(app.現在単価 || 0).toLocaleString()}</td>
          <td style="text-align: right;">¥${(app.申請単価 || 0).toLocaleString()}</td>
          <td style="text-align: center;">${changeRate}</td>
          <td style="text-align: center;">${app.承認段階 || 1}次</td>
          <td style="font-size: 11px; color: ${deadlineColor};">${deadline.toLocaleDateString()}</td>
          <td><button class="action-btn secondary select-btn" data-id="${app.申請ID}" style="padding: 4px 8px; font-size: 11px;">選択</button></td>
        </tr>
      `;
    }).join('');
  }

  // 申請詳細の表示
  function showApplicationDetail(applicationId) {
    const app = currentApplications.find(a => a.申請ID === applicationId);
    if (!app) return;

    selectedApplicationId = applicationId;

    // 詳細情報の表示
    container.querySelector('#detail-applicant').textContent = app.申請者名 || 'ユーザー' + app.申請者ID?.slice(-4);
    container.querySelector('#detail-date').textContent = new Date(app.作成日時).toLocaleString();
    container.querySelector('#detail-customer').textContent = app.顧客名 || '顧客' + app.顧客ID?.slice(-4);
    container.querySelector('#detail-product').textContent = app.商品名 || '商品' + app.商品ID?.slice(-4);
    container.querySelector('#detail-current-price').textContent = '¥' + (app.現在単価 || 0).toLocaleString();
    container.querySelector('#detail-new-price').textContent = '¥' + (app.申請単価 || 0).toLocaleString();
    container.querySelector('#detail-change-rate').innerHTML = getChangeRate(app.現在単価, app.申請単価);
    container.querySelector('#detail-reason').textContent = app.申請理由 || '理由が入力されていません';

    // 承認フローの表示（ダミーデータ）
    const workflows = [
      {
        承認段階: 1,
        承認者名: '田中 一郎',
        承認ステータス: '承認待ち',
        承認日時: null
      }
    ];
    renderApprovalFlow(workflows);

    // パネルの表示切り替え
    container.querySelector('#no-selection').style.display = 'none';
    container.querySelector('#approval-panel').style.display = 'block';
  }

  // 承認アクション実行
  async function executeApprovalAction(action) {
    if (!selectedApplicationId) return;

    const comment = container.querySelector('#approval-comment').value.trim();
    if (!comment) {
      alert('コメントを入力してください');
      return;
    }

    const statusMap = {
      'approve': '承認済',
      'reject': '却下',
      'hold': '保留'
    };

    try {
      // 単価更新申請テーブルの更新
      const updated = await window.aivicApi.update(1, selectedApplicationId, {
        申請状態: statusMap[action],
        承認者ID: 'current-user-id',
        承認日時: new Date().toISOString(),
        承認コメント: comment
      });

      if (updated) {
        // ワークフローテーブルの更新
        await window.aivicApi.update(2, selectedApplicationId, {
          承認ステータス: statusMap[action],
          承認日時: new Date().toISOString(),
          承認コメント: comment
        });

        alert(`申請を${action === 'approve' ? '承認' : action === 'reject' ? '差戻し' : '保留'}しました`);

        // 一覧を再読み込み
        const applications = await window.aivicApi.list(1);
        if (applications) {
          currentApplications = applications.filter(app => 
            ['申請中', '承認待ち', '保留'].includes(app.申請状態)
          );
          renderApplications(currentApplications);
        }

        // 詳細パネルを閉じる
        container.querySelector('#no-selection').style.display = 'block';
        container.querySelector('#approval-panel').style.display = 'none';
        selectedApplicationId = null;
        container.querySelector('#approval-comment').value = '';
      }
    } catch (error) {
      console.error('承認処理エラー:', error);
      alert('承認処理中にエラーが発生しました');
    }
  }

  // 初期データの読み込みと描画
  async function loadInitialData() {
    try {
      const applications = await window.aivicApi.list(1);
      if (applications) {
        // 承認待ちの申請のみフィルタ
        currentApplications = applications.filter(app => 
          ['申請中', '承認待ち', '保留'].includes(app.申請状態)
        );
        renderApplications(currentApplications);
      } else {
        // API未接続時は初期データを使用
        currentApplications = (tables[1]?.records || []).filter(app => 
          ['申請中', '承認待ち', '保留'].includes(app.申請状態)
        );
        renderApplications(currentApplications);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      currentApplications = (tables[1]?.records || []).filter(app => 
        ['申請中', '承認待ち', '保留'].includes(app.申請状態)
      );
      renderApplications(currentApplications);
    }
  }

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#search-input').value.trim();
    const statusFilter = container.querySelector('#status-filter').value;

    try {
      const applications = await window.aivicApi.list(1);
      if (applications) {
        let filtered = applications.filter(app => 
          ['申請中', '承認待ち', '保留'].includes(app.申請状態)
        );

        if (keyword) {
          filtered = filtered.filter(app => 
            JSON.stringify(app).toLowerCase().includes(keyword.toLowerCase())
          );
        }

        if (statusFilter) {
          filtered = filtered.filter(app => app.申請状態 === statusFilter);
        }

        currentApplications = filtered;
        renderApplications(currentApplications);
      }
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // 申請選択のイベントリスナー
  container.addEventListener('click', (e) => {
    const selectBtn = e.target.closest('.select-btn');
    const row = e.target.closest('.application-row');

    if (selectBtn || row) {
      const applicationId = selectBtn ? selectBtn.dataset.id : row.dataset.id;
      if (applicationId) {
        showApplicationDetail(applicationId);
      }
    }
  });

  // 承認アクションボタンのイベントリスナー
  container.querySelector('#btn-approve').addEventListener('click', () => {
    executeApprovalAction('approve');
  });

  container.querySelector('#btn-reject').addEventListener('click', () => {
    executeApprovalAction('reject');
  });

  container.querySelector('#btn-hold').addEventListener('click', () => {
    executeApprovalAction('hold');
  });

  // モーダルの制御
  const modal = container.querySelector('#confirm-modal');
  container.querySelector('#modal-cancel').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  // 初期データの読み込み
  loadInitialData();
}

