function(container, apiUrl, tables) {
  const tbody = container.querySelector('#period-tbody');
  const modal = container.querySelector('#add-period-modal');
  const overlapWarning = container.querySelector('#overlap-warning');

  // 1. テーブル再描画関数
  function renderRows(rows) {
    const totalCount = container.querySelector('#total-count');
    const activeCount = container.querySelector('#active-count');

    totalCount.textContent = rows.length;
    activeCount.textContent = rows.filter(r => r.適用状態 === '有効').length;

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || r.適用期間ID}">
        <td>${r.顧客名 || '未設定'}</td>
        <td>${r.商品名 || '未設定'}</td>
        <td class="text-right">${(r.適用単価 || 0).toLocaleString()}円</td>
        <td>${r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString() : '-'}</td>
        <td>${r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString() : '無期限'}</td>
        <td>
          <span class="px-2 py-1 rounded text-xs font-medium" 
                style="background: ${getStatusColor(r.適用状態)}; color: #fff;">
            ${r.適用状態 || '未設定'}
          </span>
        </td>
        <td class="text-center">${r.優先度 || 1}</td>
        <td class="text-sm" style="color: var(--text-muted);">${r.備考 || '-'}</td>
        <td>
          <div class="flex gap-1">
            <button class="action-btn secondary edit-btn text-xs px-2 py-1" data-id="${r.id || r.適用期間ID}">編集</button>
            <button class="action-btn secondary delete-btn text-xs px-2 py-1" data-id="${r.id || r.適用期間ID}">削除</button>
            <button class="action-btn secondary toggle-btn text-xs px-2 py-1" data-id="${r.id || r.適用期間ID}">
              ${r.適用状態 === '有効' ? '無効化' : '有効化'}
            </button>
          </div>
        </td>
      </tr>
    `).join('');

    // 期間重複チェック
    checkOverlaps(rows);
  }

  function getStatusColor(status) {
    switch(status) {
      case '有効': return '#22c55e';
      case '無効': return '#6b7280';
      case '予約': return '#3b82f6';
      case '期限切れ': return '#ef4444';
      default: return '#6b7280';
    }
  }

  function checkOverlaps(rows) {
    const overlaps = [];
    const activeRows = rows.filter(r => r.適用状態 === '有効');

    for (let i = 0; i < activeRows.length; i++) {
      for (let j = i + 1; j < activeRows.length; j++) {
        const row1 = activeRows[i];
        const row2 = activeRows[j];

        if (row1.顧客ID === row2.顧客ID && row1.商品ID === row2.商品ID) {
          const start1 = new Date(row1.適用開始日);
          const end1 = row1.適用終了日 ? new Date(row1.適用終了日) : new Date('2099-12-31');
          const start2 = new Date(row2.適用開始日);
          const end2 = row2.適用終了日 ? new Date(row2.適用終了日) : new Date('2099-12-31');

          if (start1 <= end2 && start2 <= end1) {
            overlaps.push({ row1, row2 });
          }
        }
      }
    }

    if (overlaps.length > 0) {
      overlapWarning.style.display = 'block';
      const details = container.querySelector('#overlap-details');
      details.innerHTML = overlaps.map(o => 
        `${o.row1.顧客名} - ${o.row1.商品名}: ${new Date(o.row1.適用開始日).toLocaleDateString()} ～ と ${new Date(o.row2.適用開始日).toLocaleDateString()} ～ が重複`
      ).join('<br>');
    } else {
      overlapWarning.style.display = 'none';
    }
  }

  // 2. 初期データ描画
  window.aivicApi.list(4).then(rows => {
    if (rows) renderRows(rows);
  });

  // 3. 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const customerSearch = container.querySelector('#customer-search').value.toLowerCase();
    const categoryFilter = container.querySelector('#category-filter').value;
    const statusFilter = container.querySelector('#status-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    const rows = await window.aivicApi.list(4);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const matchCustomer = !customerSearch || (r.顧客名 || '').toLowerCase().includes(customerSearch);
      const matchCategory = !categoryFilter || (r.商品カテゴリ || '').includes(categoryFilter);
      const matchStatus = !statusFilter || r.適用状態 === statusFilter;
      const matchStartDate = !startDate || new Date(r.適用開始日) >= new Date(startDate);
      const matchEndDate = !endDate || (r.適用終了日 && new Date(r.適用終了日) <= new Date(endDate));

      return matchCustomer && matchCategory && matchStatus && matchStartDate && matchEndDate;
    });

    renderRows(filtered);
  });

  // 条件クリア
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#customer-search').value = '';
    container.querySelector('#category-filter').value = '';
    container.querySelector('#status-filter').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';

    window.aivicApi.list(4).then(rows => {
      if (rows) renderRows(rows);
    });
  });

  // 4. 新規期間追加モーダル
  container.querySelector('#btn-add-period').addEventListener('click', () => {
    modal.style.display = 'flex';
  });

  container.querySelector('#close-modal').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  container.querySelector('#cancel-modal').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  // 5. 期間保存
  container.querySelector('#period-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      顧客ID: container.querySelector('#modal-customer').value,
      商品ID: container.querySelector('#modal-product').value,
      適用単価: parseInt(container.querySelector('#modal-price').value),
      適用開始日: container.querySelector('#modal-start-date').value,
      適用終了日: container.querySelector('#modal-end-date').value || null,
      適用状態: container.querySelector('#modal-status').value,
      優先度: parseInt(container.querySelector('#modal-priority').value),
      備考: container.querySelector('#modal-notes').value,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(4, formData);
    if (saved) {
      modal.style.display = 'none';
      container.querySelector('#period-form').reset();
      const rows = await window.aivicApi.list(4);
      if (rows) renderRows(rows);
    }
  });

  // 6. 行レベル操作（削除・編集・有効化/無効化）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const editBtn = e.target.closest('.edit-btn');
    const toggleBtn = e.target.closest('.toggle-btn');

    if (deleteBtn) {
      if (!confirm('この適用期間を削除しますか？')) return;

      await window.aivicApi.delete(4, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(4);
      if (rows) renderRows(rows);
    }

    if (editBtn) {
      // 編集機能は単価更新申請画面に遷移
      window.showScreen('scr-1780291488728');
    }

    if (toggleBtn) {
      const id = toggleBtn.dataset.id;
      const rows = await window.aivicApi.list(4);
      const row = rows.find(r => (r.id || r.適用期間ID) === id);

      if (row) {
        const newStatus = row.適用状態 === '有効' ? '無効' : '有効';
        await window.aivicApi.update(4, id, { 適用状態: newStatus, 更新日時: new Date().toISOString() });
        const updatedRows = await window.aivicApi.list(4);
        if (updatedRows) renderRows(updatedRows);
      }
    }
  });

  // 一括更新ボタン
  container.querySelector('#btn-bulk-update').addEventListener('click', () => {
    window.showScreen('scr-1780291488728');
  });
}
